public class InnerAnomalyDetectorRandomCutForestConfigurationFactory(Action<Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration>
{

    internal InnerAnomalyDetectorIgnoreNearExpectedFactory IgnoreNearExpectedFromBelowFactory { get; set; }

    internal InnerAnomalyDetectorIgnoreNearExpectedFactory IgnoreNearExpectedFromAboveFactory { get; set; }

    protected override Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration Create()
    {
        var randomCutForestConfigurationResult = CreateRandomCutForestConfiguration();
        factoryAction?.Invoke(randomCutForestConfigurationResult);

        return randomCutForestConfigurationResult;
    }

    private Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration CreateRandomCutForestConfiguration()
    {
        var randomCutForestConfigurationResult = new Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration();

        return randomCutForestConfigurationResult;
    }
    public override void CreateChildren(Humidifier.APS.AnomalyDetectorTypes.RandomCutForestConfiguration result)
    {
        base.CreateChildren(result);

        result.IgnoreNearExpectedFromBelow ??= IgnoreNearExpectedFromBelowFactory?.Build();
        result.IgnoreNearExpectedFromAbove ??= IgnoreNearExpectedFromAboveFactory?.Build();
    }

} // End Of Class

